typedef T_ThingModelReturnCode (*_AnyTypedHandler) (void *impl, void *user, const void *req, void *reply);

/* decoder: decode the req struct from the data sub-object */
typedef void (*_ReqDecoderFromObj)(const ThingModelJsonObj_t *data_obj, void *out_req);
/* encoder: typed reply struct → JSON (the content of the output sub-object) */
typedef ThingModelJsonObj_t *(*_TypedReplyEncoderAsObj)(const void *reply);
