/* CommonReply.data: {"result":N, "error_reason":"..."} */
static ThingModelJsonObj_t *_encode_common_reply_data_obj(const T_ThingModelCommonReply *r)
{
    ThingModelJsonObj_t *o = ThingModelJson_NewObject();
    if (!o) return NULL;
    ThingModelJson_AddInt   (o, "result",       r ? (int64_t)r->result : 0);
    ThingModelJson_AddString(o, "error_reason", r ? r->result_message  : "");
    return o;
}

/* typed reply.data: {"result":0, "output":{...typed...}} */
static ThingModelJsonObj_t *_wrap_typed_reply_data_obj(ThingModelJsonObj_t *output_obj)
{
    ThingModelJsonObj_t *o = ThingModelJson_NewObject();
    if (!o) { if (output_obj) ThingModelJson_Free(output_obj); return NULL; }
    ThingModelJson_AddInt(o, "result", 0);
    if (output_obj) ThingModelJson_AddObject(o, "output", output_obj);
    return o;
}

/* error fallback data: {"result":rc, "error_reason":"impl error rc=N"} */
static ThingModelJsonObj_t *_encode_error_reply_data_obj(T_ThingModelReturnCode rc)
{
    ThingModelJsonObj_t *o = ThingModelJson_NewObject();
    if (!o) return NULL;
    char msg[64];
    snprintf(msg, sizeof(msg), "impl error rc=%d", (int)rc);
    ThingModelJson_AddInt   (o, "result",       (int64_t)rc);
    ThingModelJson_AddString(o, "error_reason", msg);
    return o;
}

/* ============================================================ */
/* on_message dispatch                                            */
/* ============================================================ */

static void on_session_message(void *user, const char *topic,
                               const char *payload, size_t len)
{
    ChargingDockImpl_t *im = user;

    if (strcmp(topic, im->topic_services) != 0) return;

    ThingModelJsonObj_t *root = ThingModelJson_ParseN(payload, len);
    if (!root) return;
    T_ChargingDockEnvelope env = {0};
    if (!ChargingDock_ParseEnvelope(root, &env)) {
        ThingModelJson_Free(root);
        return;
    }

    /* snapshot the matching handler (callback outside the lock, to avoid self-deadlock) */
    SvcHandlerEntry_t snap = {0};
    bool matched = false;
    const T_ThingModelOsal *o = ThingModelClientSession_GetOsal(im->session);
    o->mutex_lock(im->lock);
    for (SvcHandlerEntry_t *e = im->svc_handlers; e; e = e->next) {
        if (env.method && strcmp(e->method, env.method) == 0) {
            snap = *e;
            matched = true;
            break;
        }
    }
    o->mutex_unlock(im->lock);
    if (!matched) { ThingModelJson_Free(root); return; }

    /* decode req from envelope.data */
    size_t reply_sz = (snap.kind == HANDLER_TYPED) ? snap.reply_size : sizeof(T_ThingModelCommonReply);
    void *req   = ThingModelMem_Calloc(1, snap.req_size);
    void *reply = ThingModelMem_Calloc(1, reply_sz);
    T_ThingModelReturnCode rc = THING_MODEL_RC_OK;
    if (!req || !reply) {
        rc = THING_MODEL_RC_OUT_OF_MEMORY;
    } else {
        if (snap.req_decoder) snap.req_decoder(env.data, req);
        if (snap.kind == HANDLER_COMMON) {
            _AnyCommonHandler h = (_AnyCommonHandler)snap.handler;
            rc = h(im, snap.user, req, (T_ThingModelCommonReply *)reply);
        } else {
            _AnyTypedHandler h = (_AnyTypedHandler)snap.handler;
            rc = h(im, snap.user, req, reply);
        }
    }

    /* build reply data obj */
    ThingModelJsonObj_t *reply_data_obj = NULL;
    if (THING_MODEL_IS_OK(rc)) {
        if (snap.kind == HANDLER_COMMON) {
            reply_data_obj = _encode_common_reply_data_obj((T_ThingModelCommonReply *)reply);
        } else if (snap.reply_encoder) {
            ThingModelJsonObj_t *output_obj = snap.reply_encoder(reply);
            reply_data_obj = _wrap_typed_reply_data_obj(output_obj);
        }
    }
    if (!reply_data_obj) {
        reply_data_obj = _encode_error_reply_data_obj(THING_MODEL_IS_OK(rc) ? THING_MODEL_RC_OUT_OF_MEMORY : rc);
    }

    /* serialize data obj → str, then wrap the envelope. free data_json after use */
    char *reply_data_json = reply_data_obj ? ThingModelJson_PrintCompact(reply_data_obj) : NULL;
    if (reply_data_obj) ThingModelJson_Free(reply_data_obj);
    char *wire = ChargingDock_EncodeReply(env.bid, env.tid, env.method, env.version, reply_data_json);
    if (wire) {
        ThingModelClientSession_Publish(im->session, im->topic_services_reply, wire, 1);
        ThingModelMem_Free(wire);
    }
    ThingModelMem_Free(reply_data_json);
    if (req   && snap.req_free)   snap.req_free(req);
    if (reply && snap.reply_free) snap.reply_free(reply);
    ThingModelMem_Free(req);
    ThingModelMem_Free(reply);
    ThingModelJson_Free(root);
}

/* ============================================================ */
/* Create / Destroy                                              */
/* ============================================================ */

ChargingDockImpl_t *ChargingDockImpl_Create(ThingModelClientSession_t *session, const char *device_id)
{
    if (!session || !device_id || !device_id[0]) return NULL;
    const T_ThingModelOsal *o = ThingModelClientSession_GetOsal(session);
    ChargingDockImpl_t *im = ThingModelMem_Calloc(1, sizeof(*im));
    if (!im) return NULL;
    im->session = session;
    im->lock    = o->mutex_create();
    snprintf(im->device_id, sizeof(im->device_id), "%s", device_id);
    build_dock_topic(im->topic_services,       sizeof(im->topic_services),       im->device_id, CHARGING_DOCK_CHANNEL_SERVICES);
    build_dock_topic(im->topic_services_reply, sizeof(im->topic_services_reply), im->device_id, CHARGING_DOCK_CHANNEL_SERVICES_REPLY);

    im->listener_handle = ThingModelClientSession_AddListener(session, on_session_message, im);
    ThingModelClientSession_Subscribe(session, im->topic_services, 1);
    return im;
}

void ChargingDockImpl_Destroy(ChargingDockImpl_t *im)
{
    if (!im) return;
    const T_ThingModelOsal *o = ThingModelClientSession_GetOsal(im->session);
    ThingModelClientSession_RemoveListener(im->session, im->listener_handle);
    ThingModelClientSession_Unsubscribe(im->session, im->topic_services);
    SvcHandlerEntry_t *e = im->svc_handlers;
    while (e) { SvcHandlerEntry_t *n = e->next; ThingModelMem_Free(e); e = n; }
    if (im->lock) o->mutex_destroy(im->lock);
    ThingModelMem_Free(im);
}

/* ============================================================ */
/* SERVICE handler registration                                  */
/* ============================================================ */

static T_ThingModelReturnCode register_svc_handler(ChargingDockImpl_t *im,
                                                   const char *method,
                                                   EHandlerKind kind,
                                                   void *handler, void *user,
                                                   _ReqDecoderFromObj req_decoder,
                                                   _TypedReplyEncoderAsObj reply_encoder,
                                                   _StructFree req_free,
                                                   _StructFree reply_free,
                                                   size_t req_size, size_t reply_size)
{
    if (!im || !method) return THING_MODEL_RC_INVALID_ARG;
    const T_ThingModelOsal *o = ThingModelClientSession_GetOsal(im->session);

    o->mutex_lock(im->lock);
    SvcHandlerEntry_t *e = im->svc_handlers;
    while (e) { if (strcmp(e->method, method) == 0) break; e = e->next; }
    if (handler == NULL) {
        if (e) {
            SvcHandlerEntry_t **pp = &im->svc_handlers;
            while (*pp != e) pp = &(*pp)->next;
            *pp = e->next;
            ThingModelMem_Free(e);
        }
        o->mutex_unlock(im->lock);
        return THING_MODEL_RC_OK;
    }
    if (!e) {
        e = ThingModelMem_Calloc(1, sizeof(*e));
        if (!e) { o->mutex_unlock(im->lock); return THING_MODEL_RC_OUT_OF_MEMORY; }
        snprintf(e->method, sizeof(e->method), "%s", method);
        e->next = im->svc_handlers;
        im->svc_handlers = e;
    }
    e->kind          = kind;
    e->handler       = handler;
    e->user          = user;
    e->req_decoder   = req_decoder;
    e->reply_encoder = reply_encoder;
    e->req_free      = req_free;
    e->reply_free    = reply_free;
    e->req_size      = req_size;
    e->reply_size    = reply_size;
    o->mutex_unlock(im->lock);
    return THING_MODEL_RC_OK;
}


